  webimg: { id: 'webimg', ico: '🖼️', n: 'Connector/a de pàgines|Conector/a de páginas', d: "Imatges, enllaços i fonts ben citades: la fitxa d'un animal.|Imágenes, enlaces y fuentes bien citadas: la ficha de un animal." },
  webcss: { id: 'webcss', ico: '🎨', n: 'Estilista CSS|Estilista CSS', d: 'Has donat color i lletra a una pàgina: el pòster.|Has dado color y letra a una página: el póster.' },
  webbox: { id: 'webbox', ico: '📦', n: 'Arquitecte/a de caixes|Arquitecto/a de cajas', d: 'Marges, farciment, vores i ombres: la targeta del videojoc.|Márgenes, relleno, bordes y sombras: la tarjeta del videojuego.' },
  weblay: { id: 'weblay', ico: '🧩', n: 'Maquetador/a|Maquetador/a', d: "Files, graelles i taules: l'àlbum de fotos.|Filas, rejillas y tablas: el álbum de fotos." },
  webmob: { id: 'webmob', ico: '📱', n: 'Dissenyador/a mòbil|Diseñador/a móvil', d: 'Webs que s\'adapten a qualsevol pantalla: la guia de Lleida.|Webs que se adaptan a cualquier pantalla: la guía de Lleida.' },
  webfin: { id: 'webfin', ico: '🚀', n: 'Creador/a web|Creador/a web', d: 'Has planificat, construït i presentat la teva pròpia web.|Has planificado, construido y presentado tu propia web.' }
