  const R_HTML = qui => doc('Refugi Bigotis', `    <header>\n      <h1>Refugi Bigotis</h1>\n      <nav>\n        <a href="#qui-som">Qui som</a>\n        <a href="#animals">Animals</a>\n        <a href="#ajuda">Ajuda'ns</a>\n      </nav>\n    </header>\n    <main>\n${qui}\n      <section id="animals">\n        <h2>Busquen casa</h2>\n        <div class="animals">\n          <article class="animal">\n            <img src="img/gat.svg" alt="Gat taronja estirat">\n            <h3>Mixa</h3>\n            <p>Té 2 anys i li encanta dormir al sol.</p>\n          </article>\n          <article class="animal">\n            <img src="img/tortuga.svg" alt="Tortuga verda caminant">\n            <h3>Lenta</h3>\n            <p>És molt tranquil·la i menja enciam.</p>\n          </article>\n          <article class="animal">\n            <img src="img/lloro.svg" alt="Lloro de colors">\n            <h3>Pipo</h3>\n            <p>Sap dir «hola» i xiula cançons.</p>\n          </article>\n        </div>\n      </section>\n      <section id="ajuda">\n        <h2>Ajuda'ns</h2>\n        <p>Pots fer de voluntari/a amb un adult o portar mantes velles.</p>\n        <a class="boto" href="#qui-som">Vull ajudar</a>\n      </section>\n    </main>\n    <footer>\n      <p>Refugi Bigotis · web d'exemple del curs</p>\n    </footer>`);
  const R0 = R_HTML(R_QUI0), R1 = R_HTML(R_QUI1);
  const RC_A = `body {\n  margin: 0;\n}\nimg {\n  width: 110px;\n}\nheader {\n  padding: 12px 20px;\n}\nnav a {\n  margin-left: 12px;\n}\nmain {\n  padding: 16px 20px;\n}\nfooter {\n  padding: 12px 20px;\n}`;
  const RC_PAL = `\n/* paleta: fons #fff8ef · text #2d2a32 · principal #b5402a · suau #ffe8d6 */\nbody {\n  font-family: 'Trebuchet MS', sans-serif;\n  background-color: #fff8ef;\n  color: #2d2a32;\n}\nh1, h2 {\n  font-family: Georgia, serif;\n  color: #b5402a;\n}\nheader, footer {\n  background-color: #ffe8d6;\n}`;
  const RC_BOX = `\n.animal {\n  background-color: white;\n  padding: 14px;\n  border-radius: 12px;\n  box-shadow: 0 4px 10px #ffe8d6;\n}`;
  const RC_FLEX = `\nheader {\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n}\nnav a {\n  color: #b5402a;\n  text-decoration: none;\n  font-weight: bold;\n}`;
